const registerWeatherTool = (registry: ToolRegistry, execute: (input: Record<string, unknown>) => Promise<string>) => {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    execute
  );
};

