    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {location: 123});

    expect(response.result).toMatch(/^\/location must be string$/);
    expect(executor).not.toHaveBeenCalled();
  });

